// src/hooks/use-sync-outbox-on-foreground.ts
// Every job of the build on app active, through the job list: the job file's only importer is
// background-jobs.ts (inside the background folder), and this hook calls runBackgroundJob itself.
import { useEffect } from 'react';

import { useIsAppActive } from '@/hooks/use-is-app-active';
import { runBackgroundJob } from '@/services/background-tasks/background-job';
import { BACKGROUND_JOBS } from '@/services/background-tasks/background-jobs';

import type { JobEnvironment } from '@/services/background-tasks/background-job';
import type { BackgroundDeps } from '@/services/background-tasks/background-jobs';

export function useBackgroundJobsOnForeground(environment: JobEnvironment<BackgroundDeps>): void {
  const isActive = useIsAppActive();
  useEffect(() => {
    if (!isActive) return;
    for (const job of BACKGROUND_JOBS) {
      runBackgroundJob(job, environment, { trigger: 'foreground' }).catch((thrown: unknown) => {
        environment.errorLog.record('service', thrown);
      });
    }
  }, [isActive, environment]);
}

// src/services/background-tasks/jobs/record-location-job.ts
// A location task's job: the task body's { locations } arrive as context.input, a TaskManagerError as
// context.error. Each point is stored on its own (one commit per step), keyed by its timestamp.
import * as v from 'valibot';

import { defineBackgroundJob } from '@/services/background-tasks/background-job';

const INPUT = v.object({
  locations: v.array(v.object({ timestamp: v.number(), coords: v.object({ latitude: v.number(), longitude: v.number() }) })),
});

export type RecordLocationDeps = {
  readonly track: { readonly savePoint: (timestamp: number, latitude: number, longitude: number) => boolean };
};

export const recordLocationJob = defineBackgroundJob<RecordLocationDeps>({
  name: 'tracks.record-location',
  budgetMs: 5_000,
  run: ({ deps, input, error, shouldStop }) => {
    if (error !== null) return Promise.resolve({ kind: 'failed', reason: 'location-error' });
    const parsed = v.safeParse(INPUT, input);
    if (!parsed.success) return Promise.resolve({ kind: 'failed', reason: 'location-input-invalid' });
    let processed = 0;
    for (const point of parsed.output.locations) {
      if (shouldStop()) return Promise.resolve({ kind: 'partial', processed });
      if (!deps.track.savePoint(point.timestamp, point.coords.latitude, point.coords.longitude)) {
        return Promise.resolve({ kind: 'failed', reason: 'track-unwritable' });
      }
      processed += 1;
    }
    return Promise.resolve({ kind: 'done', processed });
  },
});

// src/services/background-tasks/jobs/record-location-job.test.ts
import { runJobTwice, runJobUntilAborted } from '@test/background/job-test-kit';

import { recordLocationJob } from './record-location-job';

const input = { locations: [{ timestamp: 1, coords: { latitude: 0, longitude: 0 } }, { timestamp: 2, coords: { latitude: 1, longitude: 1 } }] };

function track(): { readonly saved: Map<number, string>; readonly deps: Parameters<typeof recordLocationJob.run>[0]['deps'] } {
  const saved = new Map<number, string>();
  return { saved, deps: { track: { savePoint: (at, lat, lon) => { saved.set(at, `${String(lat)},${String(lon)}`); return true; } } } };
}

describe('recordLocationJob', () => {
  it('stores each point once, however often the same payload runs', async () => {
    const app = track();
    await runJobTwice(recordLocationJob, app.deps, { input });
    expect([...app.saved.keys()]).toStrictEqual([1, 2]);
  });

  it('keeps the points stored before a stop', async () => {
    const app = track();
    const stopped = await runJobUntilAborted(recordLocationJob, app.deps, { stopAfterChecks: 1, input });
    expect([stopped.outcome, [...app.saved.keys()]]).toStrictEqual([{ kind: 'partial', processed: 1 }, [1]]);
  });
});

// src/services/background-tasks/define-location-tasks.ts
// The location task registry: the entry imports it next to define-background-tasks.ts. The task is
// registered by expo-location (startLocationUpdatesAsync(recordLocationJob.name, ...)), not by the
// background-task reconcile, so the job stays out of BACKGROUND_JOBS.
import * as TaskManager from 'expo-task-manager';

import { createBackgroundEnvironment } from './background-environment';
import { recordLocationJob } from './jobs/record-location-job';
import { toTaskExecutor } from './task-executor';

TaskManager.defineTask(recordLocationJob.name, toTaskExecutor(recordLocationJob, createBackgroundEnvironment));

// src/features/tracking/use-record-location-while-open.ts
// The location job's foreground path: while the app is open, the position watch (through the app's
// location port) hands each update to the same job, through the same runner, as a foreground run.
import { useEffect } from 'react';

import { runBackgroundJob } from '@/services/background-tasks/background-job';
import { recordLocationJob } from '@/services/background-tasks/jobs/record-location-job';

import type { JobEnvironment } from '@/services/background-tasks/background-job';
import type { RecordLocationDeps } from '@/services/background-tasks/jobs/record-location-job';
import type { LocationPort } from '@/services/location/location-port';

export function useRecordLocationWhileOpen(location: LocationPort, environment: JobEnvironment<RecordLocationDeps>): void {
  useEffect(
    () =>
      location.watchPosition((update) => {
        runBackgroundJob(recordLocationJob, environment, { trigger: 'foreground', input: { locations: [update] } }).catch((thrown: unknown) => {
          environment.errorLog.record('service', thrown);
        });
      }),
    [location, environment],
  );
}
